class Path:
    def __init__(self,start=None):
        self.p=np.array(start if start is not None else obs.group('tcp_pose',now=True)[:3]); self.rows=[]
    def go(self,p,speed=.02,hold=0):
        p=np.asarray(p); n=max(1,int(np.ceil(np.linalg.norm(p-self.p)/speed/.05)))
