        # Place component 2 in the vacant practice band, exact physical size.
        uv=uv-np.array([470,376])
        xyz=np.c_[-.087-uv[:,1]*mm,-.1856-uv[:,0]*mm,np.full(len(uv),zpaper-pressure)]
